import bpy

bl_info = {
    "name": "AI 3D Model Quick Cleaner",
    "author": "Pipeline TD",
    "version": (1, 0, 0),
    "blender": (4, 0, 0),
    "location": "View3D > Sidebar > AI Clean",
    "description": "Cleans up AI-generated meshes locally in Blender",
    "category": "Mesh",
}

class AI3DCleanerOperator(bpy.types.Operator):
    """Clean up selected AI generated meshes"""
    bl_idname = "object.ai_3d_cleaner"
    bl_label = "Clean AI Mesh"
    bl_options = {'REGISTER', 'UNDO'}

    def execute(self, context):
        # Ensure we are in OBJECT mode
        if bpy.context.active_object and bpy.context.active_object.mode != 'OBJECT':
            bpy.ops.object.mode_set(mode='OBJECT')

        selected_objects = context.selected_objects
        if not selected_objects:
            self.report({'WARNING'}, "No objects selected")
            return {'CANCELLED'}

        for obj in selected_objects:
            if obj.type == 'MESH':
                context.view_layer.objects.active = obj
                # Apply scale and rotation
                bpy.ops.object.transform_apply(location=False, rotation=True, scale=True)

                # Switch to edit mode for mesh cleanup
                bpy.ops.object.mode_set(mode='EDIT')
                # Remove loose geometry
                bpy.ops.mesh.delete_loose()
                # Remove doubles (merge by distance)
                bpy.ops.mesh.remove_doubles(threshold=0.0001)
                bpy.ops.object.mode_set(mode='OBJECT')

        self.report({'INFO'}, "AI Mesh cleanup completed successfully.")
        return {'FINISHED'}

class VIEW3D_PT_ai_cleaner_panel(bpy.types.Panel):
    """Panel for AI 3D Model Cleaner"""
    bl_label = "AI 3D Quick Cleaner"
    bl_idname = "VIEW3D_PT_ai_cleaner_panel"
    bl_space_type = 'VIEW_3D'
    bl_region_type = 'UI'
    bl_category = "AI Clean"

    def draw(self, context):
        layout = self.layout
        layout.operator("object.ai_3d_cleaner")

classes = (
    AI3DCleanerOperator,
    VIEW3D_PT_ai_cleaner_panel,
)

def register():
    for cls in classes:
        bpy.utils.register_class(cls)

def unregister():
    for cls in reversed(classes):
        bpy.utils.unregister_class(cls)

if __name__ == "__main__":
    register()
